// ─── 5. Prestige Titles ───────────────────────────────────────────────────────

@Composable
fun EquippedTitlesSection() {
    val infiniteTransition = rememberInfiniteTransition(label = "aura")
    val auraAlpha by infiniteTransition.animateFloat(
        initialValue = 0.4f, targetValue = 1f, label = "aura_alpha",
        animationSpec = infiniteRepeatable(tween(2000, easing = EaseInOut), RepeatMode.Reverse)
    )

    Column {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(horizontal = 20.dp),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Text(
                "PRESTIGE TITLES",
                fontSize = 11.sp,
                fontWeight = FontWeight.Bold,
                color = NavyDeep.copy(0.4f),
                letterSpacing = 1.sp
            )
            Text(
                "VIEW ALL",
                fontSize = 9.sp,
                fontWeight = FontWeight.Bold,
                color = PrimaryGreen,
                letterSpacing = 0.8.sp
            )
        }

        Spacer(modifier = Modifier.height(12.dp))

        LazyRow(
            contentPadding = PaddingValues(horizontal = 20.dp),
            horizontalArrangement = Arrangement.spacedBy(16.dp)
        ) {
            item {
                TitleBadge(
                    name = "Champion",
                    icon = Icons.Default.EmojiEvents,
                    isActive = true,
                    auraAlpha = auraAlpha
                )
            }
            item {
                TitleBadge(name = "Hot Streak", icon = Icons.Default.LocalFireDepartment, isActive = false)
            }
            item {
                TitleBadge(name = "Power Serve", icon = Icons.Default.Bolt, isActive = false)
            }
            item {
                TitleBadge(name = "Locked", icon = Icons.Default.Lock, isActive = false, isLocked = true)
            }
        }
    }
}

@Composable
fun TitleBadge(
    name: String,
    icon: ImageVector,
    isActive: Boolean,
    isLocked: Boolean = false,
    auraAlpha: Float = 1f
) {
    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.spacedBy(10.dp),
        modifier = Modifier
            .width(88.dp)
            .then(if (isLocked) Modifier.alpha(0.5f) else Modifier)
    ) {
        Box(
            modifier = Modifier.size(76.dp),
            contentAlignment = Alignment.Center
        ) {
            // Aura glow background
            if (isActive) {
                Box(
                    modifier = Modifier
                        .size(76.dp)
                        .background(
                            Brush.radialGradient(
                                colors = listOf(PrimaryGreen.copy(0.35f * auraAlpha), Color.Transparent)
                            ),
                            CircleShape
                        )
                )
            }

            Surface(
                modifier = Modifier.size(60.dp),
                shape = RoundedCornerShape(14.dp),
                color = if (isLocked) CoolGray else if (isActive) CoolGray.copy(0.35f) else Color.White,
                border = BorderStroke(1.dp, if (isActive) CoolGray else CoolGray),
                shadowElevation = if (isActive) 0.dp else 2.dp
            ) {
                Box(contentAlignment = Alignment.Center) {
                    Icon(
                        icon,
                        contentDescription = null,
                        tint = if (isLocked) NavyDeep.copy(0.3f) else NavyDeep,
                        modifier = Modifier.size(28.dp)
                    )
                }
            }

            // Active dot indicator
            if (isActive) {
                Box(
                    modifier = Modifier
                        .size(7.dp)
                        .align(Alignment.BottomCenter)
                        .offset(y = 2.dp)
                        .background(PrimaryGreen, CircleShape)
                        .shadow(4.dp, CircleShape, spotColor = PrimaryGreen)
                )
            }
        }

        Text(
            name.uppercase(),
            fontSize = 9.sp,
            fontWeight = if (isActive) FontWeight.Black else FontWeight.Bold,
            color = if (isActive) NavyDeep else NavyDeep.copy(0.55f),
            textAlign = TextAlign.Center,
            letterSpacing = 0.8.sp,
            lineHeight = 13.sp
        )
    }
}


// ─── 6. Account Section ──────────────────────────────────────────────────────

@Composable
fun AccountSection(onSettingsClick: () -> Unit = {}) {
    Column {
        Text(
            "ACCOUNT",
            fontSize = 11.sp,
            fontWeight = FontWeight.Bold,
            color = NavyDeep.copy(0.4f),
            letterSpacing = 1.sp
        )
        Spacer(modifier = Modifier.height(12.dp))
        Surface(
            shape = RoundedCornerShape(18.dp),
            color = Color.White,
            border = BorderStroke(1.dp, CoolGray.copy(0.7f)),
            shadowElevation = 1.dp
        ) {
            Column {
                AccountItem(title = "Settings", icon = Icons.Outlined.Tune, onClick = onSettingsClick)
                HorizontalDivider(color = CoolGray.copy(0.6f), thickness = 0.8.dp)
                AccountItem(title = "Notifications", icon = Icons.Outlined.Notifications)
            }
        }
    }
}

@Composable
fun AccountItem(
    title: String,
    icon: ImageVector,
    titleColor: Color = NavyDeep,
    onClick: () -> Unit = {}
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable { onClick() }
            .padding(16.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Row(
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(12.dp)
        ) {
            Box(
                modifier = Modifier
                    .size(34.dp)
                    .background(CoolGray.copy(0.5f), RoundedCornerShape(9.dp)),
                contentAlignment = Alignment.Center
            ) {
                Icon(icon, contentDescription = null, tint = titleColor, modifier = Modifier.size(18.dp))
            }
            Text(title, fontSize = 14.sp, fontWeight = FontWeight.Medium, color = titleColor)
        }
        Icon(Icons.AutoMirrored.Filled.KeyboardArrowRight, contentDescription = null, tint = NavyDeep.copy(0.3f))
    }
}

fun Modifier.blur(radius: androidx.compose.ui.unit.Dp) = this.then(
    Modifier.drawBehind { drawRect(Color.Transparent) }
)

@Composable
fun MeshBackground() {
    Box(modifier = Modifier.fillMaxSize().background(Color.White)) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(
                    Brush.radialGradient(
                        colors = listOf(SoftMint.copy(0.55f), Color.Transparent),
                        center = Offset(1200f, 0f),
                        radius = 900f
                    )
                )
        )
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(
                    Brush.radialGradient(
                        colors = listOf(CoolGray.copy(0.5f), Color.Transparent),
                        center = Offset(0f, 0f),
                        radius = 700f
                    )
                )
        )
        Box(
            modifier = Modifier
                .fillMaxSize()
                .background(
                    Brush.radialGradient(
                        colors = listOf(PrimaryGreen.copy(0.12f), Color.Transparent),
                        center = Offset(400f, 2200f),
                        radius = 800f
                    )
                )
        )
    }
}

@Composable
fun RefereeHubSection(
    state: UiState<com.example.pickleball.data.model.RefereeProfileDTO?>,
    onTakeQuiz: () -> Unit,
    onRefMatches: () -> Unit
) {
    Surface(
        modifier = Modifier
            .fillMaxWidth()
            .shadow(4.dp, RoundedCornerShape(16.dp)),
        color = Color(0xFF1E293B),
        shape = RoundedCornerShape(16.dp)
    ) {
        when (state) {
            is UiState.Loading -> {
                Box(modifier = Modifier.padding(20.dp), contentAlignment = Alignment.Center) {
                    CircularProgressIndicator(color = PrimaryGreen, modifier = Modifier.size(24.dp))
                }
            }
            is UiState.Success -> {
                val profile = state.data
                if (profile == null) {
                    // Not a referee yet -> Show Registration Banner
                    Row(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { onTakeQuiz() }
                            .padding(20.dp),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Column(modifier = Modifier.weight(1f)) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(Icons.Default.Shield, contentDescription = null, tint = PrimaryGreen, modifier = Modifier.size(18.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text("AI REFEREE CERTIFICATION", color = PrimaryGreen, fontWeight = FontWeight.Black, fontSize = 10.sp, letterSpacing = 1.sp)
                            }
                            Spacer(modifier = Modifier.height(4.dp))
                            Text("Unlock Referee Mode", color = Color.White, fontWeight = FontWeight.Bold, fontSize = 16.sp)
                            Text("Earn tokens by officiating ranked matches.", color = Color.White.copy(0.6f), fontSize = 12.sp)
                        }
                        Icon(Icons.AutoMirrored.Filled.ArrowForward, contentDescription = null, tint = PrimaryGreen)
                    }
                } else {
                    // Certified Referee Dashboard
                    Column(
                        modifier = Modifier.fillMaxWidth().padding(20.dp)
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.SpaceBetween,
                            modifier = Modifier.fillMaxWidth()
                        ) {
                            Row(verticalAlignment = Alignment.CenterVertically) {
                                Icon(Icons.Default.Verified, contentDescription = null, tint = GoldColor, modifier = Modifier.size(20.dp))
                                Spacer(modifier = Modifier.width(6.dp))
                                Text("CERTIFIED REFEREE", color = GoldColor, fontWeight = FontWeight.Black, fontSize = 10.sp, letterSpacing = 1.sp)
                            }
                            Text("TRUST: ${profile.trustScore ?: 100}", color = PrimaryGreen, fontWeight = FontWeight.Bold, fontSize = 12.sp)
                        }
                        Spacer(modifier = Modifier.height(16.dp))
                        Row(horizontalArrangement = Arrangement.spacedBy(16.dp)) {
                            Column(modifier = Modifier.weight(1f)) {
                                Text("${profile.totalMatchesRefereed ?: 0}", color = Color.White, fontWeight = FontWeight.Black, fontSize = 24.sp)
                                Text("MATCHES", color = Color.White.copy(0.5f), fontWeight = FontWeight.Bold, fontSize = 10.sp)
                            }
                            Button(
                                onClick = onRefMatches,
                                colors = ButtonDefaults.buttonColors(containerColor = PrimaryGreen),
                                shape = RoundedCornerShape(8.dp)
                            ) {
                                Text("FIND MATCHES", color = NavyDeep, fontWeight = FontWeight.Bold, fontSize = 12.sp)
                            }
                        }
                    }
                }
            }
            else -> {}
        }
    }
}
